#!/bin/bash
set -e

# NOTE: FULLY GENERATED by Gemini-2.5-Pro

# The path to the config file inside the container.
# It's in the /shared volume, which is where the symlink in /opt/seafile/conf points.
GUNICORN_CONFIG="/shared/seafile/conf/gunicorn.conf.py"

# Function to patch the gunicorn config
patch_gunicorn_conf() {
    echo "Gunicorn config found. Patching bind address..."
    # Use sed to replace the line. This is safer than replacing the whole file.
    sed -i 's/bind = "127.0.0.1:8000"/bind = "0.0.0.0:8000"/' "$GUNICORN_CONFIG"
    echo "Config patched successfully."
}

# The main logic
# First, run the original entrypoint script to let it set everything up.
# We need to run this in the background to monitor it.
/sbin/my_init -- /scripts/enterpoint.sh &
ENTRYPOINT_PID=$!

echo "Waiting for the initial setup to generate the gunicorn config file..."
while true; do
    # Check if the entrypoint process is still alive. If not, something went wrong.
    if ! ps -p $ENTRYPOINT_PID > /dev/null; then
        echo "The container's main setup process exited unexpectedly. Aborting."
        exit 1
    fi

    # If the config file exists, patch it and break the loop.
    if [ -f "$GUNICORN_CONFIG" ]; then
        patch_gunicorn_conf
        break
    fi

    sleep 1
done

echo "Setup and patching complete. The server will now start."

# Wait for the original entrypoint process to finish or continue running.
# This ensures our container stays alive, running the main Seafile processes.
wait $ENTRYPOINT_PID 